void SectorLeaderPage::loadHistory(){clean();need(!historyBoardId.isEmpty(),"请选择人工板块或已删除板块历史");auto path=file,id=historyBoardId;int offset=historyOffset;run([path,id,offset](auto cancel){sectorLeader::Store s(path);return QJsonObject{{"rows",s.history(id,offset,20,cancel)},{"count",s.count(id,cancel)}};},[this](QJsonObject data){bool full=tabs->currentIndex()==5;history=data["rows"].toArray();historyCount=data["count"].toInt();rendering=true;tabs->setCurrentIndex(2);historyList->setRowCount(0);for(auto v:history){auto s=v.toObject(),m=s["summary"].toObject();int i=historyList->rowCount();historyList->insertRow(i);QStringList cells{s["capturedAt"].toString(),s["sectorName"].toString(),m["status"].toString()+QString(" · %1/%2").arg(m["validCount"].toInt()).arg(m["memberCount"].toInt())};for(int j=0;j<cells.size();j++)historyList->setItem(i,j,new QTableWidgetItem(cells[j]));historyList->item(i,0)->setData(Qt::UserRole,s);}rendering=false;int selected=-1;for(int i=0;i<historyList->rowCount();++i)if(historyList->item(i,0)->data(Qt::UserRole).toJsonObject()["id"].toString()==historySelection)selected=i;if(selected>=0)historyList->selectRow(selected);if(full){if(selected>=0)readHistoryOriginal();else{originalFull="原选中观察已不存在；没有按名称或代码替换记录。";originalOffset=0;renderHistoryOriginal();rendering=true;tabs->setCurrentIndex(5);rendering=false;}}state->setText(QString("冻结历史 %1-%2 / %3；旧记录无历史配置；原时串与数值保留，按SQLite文本排序").arg(historyOffset+(history.isEmpty()?0:1)).arg(historyOffset+history.size()).arg(historyCount));});}
void SectorLeaderPage::archivedHistory(){clean();auto path=file;run([path](auto cancel){return QJsonObject{{"boards",sectorLeader::Store(path).historyBoards(cancel)}};},[this](QJsonObject result){QStringList labels,ids;for(auto v:result["boards"].toArray()){auto b=v.toObject();bool live=false;for(auto current:config["sectors"].toArray())if(current.toObject()["id"]==b["id"])live=true;if(!live){ids<<b["id"].toString();labels<<b["id"].toString()+QString("（%1条）").arg(b["count"].toInt());}}need(!ids.isEmpty(),"没有已删除板块冻结历史");bool ok;auto label=QInputDialog::getItem(this,"保留的已删除板块历史","按原板块身份选择",labels,0,false,&ok);if(ok){historyBoardId=ids[labels.indexOf(label)];historyOffset=0;loadHistory();}});}
