void SectorLeaderPage::renderHistoryOriginal(){if(originalOffset>=originalFull.size())originalOffset=0;originalText->setPlainText(originalFull.mid(originalOffset,32768));originalPrevious->setEnabled(originalOffset>0);originalNext->setEnabled(originalOffset+32768<originalFull.size());originalText->setToolTip(QString("完整原字段共%1字符；当前%2至%3，分段显示，不截断留存记录").arg(originalFull.size()).arg(originalOffset+1).arg(qMin<qsizetype>(originalFull.size(),originalOffset+32768)));}
void SectorLeaderPage::prune(){clean();need(historyCount>0&&!historyBoardId.isEmpty(),"先读取冻结历史");bool ok;int keep=QInputDialog::getInt(this,"明确清理历史","仅该板块：按原时间文本/原ID倒序保留（至少1）；旧时区未知，混合原生记录拒绝清理",20,1,8000,1,&ok);if(!ok||keep>=historyCount)return;if(QMessageBox::question(this,"确认清理",QString("删除该板块最旧%1条冻结记录，保留最近%2条？").arg(historyCount-keep).arg(keep))!=QMessageBox::Yes)return;auto path=file,id=historyBoardId;int count=historyCount;run([path,id,keep,count](auto cancel){return QJsonObject{{"removed",sectorLeader::Store(path).prune(id,keep,count,cancel)}};},[this](QJsonObject){historyOffset=0;loadHistory();});}
void SectorLeaderPage::refresh(){clean();need(allowNetwork,"当前运行未启用网络");auto b=currentBoard();need(b["leaders"].toArray().size()<=100,"当前板块单次最多100候选，不静默截取");QStringList ids;for(auto v:b["leaders"].toArray()){auto r=v.toObject();auto id=r["fullId"].toString();if(!id.isEmpty()&&!ids.contains(id)){sectorLeader::identity(id,r["code"].toString());ids<<id;}}need(!ids.isEmpty(),"本板块全为身份待核，未发送网络请求");cancel();busy=true;networkToken=++generation;pendingIds=ids;pendingQuotes=quotes;deadline->start(8000);state->setText("仅读取当前人工板块报价；8秒总期限，不自动冻结");controls();nextQuote();}
void SectorLeaderPage::nextQuote(){if(!busy||networkToken!=generation)return;if(pendingIds.isEmpty()){finishQuotes({});return;}QStringList batch;while(!pendingIds.isEmpty()&&batch.size()<50)batch<<pendingIds.takeFirst();QStringList symbols;for(auto id:batch)symbols<<id.left(2).toLower()+id.section(':',2,2);QNetworkRequest req(QUrl("https://hq.sinajs.cn/list="+symbols.join(',')));req.setRawHeader("Referer","https://finance.sina.com.cn/");req.setRawHeader("User-Agent","Mozilla/5.0");req.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::ManualRedirectPolicy);reply=transport->get(req);auto response=reply;auto token=networkToken;replyBytes.clear();responseTooLarge=false;connect(response,&QIODevice::readyRead,this,[this,response,token]{if(reply!=response||token!=generation)return;auto part=response->readAll();if(replyBytes.size()+part.size()>2097152){responseTooLarge=true;response->abort();}else replyBytes.append(part);});connect(response,&QNetworkReply::finished,this,[this,response,token,batch,symbols]{if(reply!=response||token!=generation)return;auto tail=response->readAll();if(replyBytes.size()+tail.size()>2097152)responseTooLarge=true;else replyBytes.append(tail);QString error=responseTooLarge?"报价返回超过2MiB":response->error()!=QNetworkReply::NoError?response->errorString():response->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt()!=200?"报价HTTP状态非200":QString();reply=nullptr;response->deleteLater();auto result=error.isEmpty()?marketdata::quotes(marketdata::decodeQuote(replyBytes),at()):QJsonObject{};for(int i=0;i<batch.size();i++){auto q=result[symbols[i]].toObject();if(error.isEmpty()&&!q.isEmpty()){q["cached"]=false;q["error"]="";pendingQuotes[batch[i]]=q;}else{auto old=quotes[batch[i]].toObject();old["cached"]=true;old["error"]=error.isEmpty()?"来源未返回此完整身份":error;old["lastAttemptAt"]=at();pendingQuotes[batch[i]]=old;}}nextQuote();});}
void SectorLeaderPage::finishQuotes(QString error){if(!busy||networkToken!=generation)return;deadline->stop();if(reply){auto response=reply;reply=nullptr;response->disconnect(this);response->abort();response->deleteLater();}if(!error.isEmpty()){auto b=currentBoard();for(auto v:b["leaders"].toArray()){auto id=v.toObject()["fullId"].toString();if(id.isEmpty())continue;auto q=quotes[id].toObject();q["cached"]=true;q["error"]=error;q["lastAttemptAt"]=at();pendingQuotes[id]=q;}}quotes=pendingQuotes;pendingIds.clear();busy=false;render();state->setText(error.isEmpty()?"范围报价完成；缺数 / 来源时点 / 错误保留，未保存观察":error);controls();}
void SectorLeaderPage::updateInstrument(const QJsonObject& s){QJsonObject r;try{r=selected();}catch(...){return;}if(r["fullId"].toString().isEmpty()||s["id"]!=r["fullId"])return;
 auto* repaint=static_cast<VisibleRefresh*>(findChild<QObject*>("minuteRefresh",Qt::FindDirectChildrenOnly));
 if(!repaint){repaint=new VisibleRefresh(this);repaint->setObjectName("minuteRefresh");repaint->refresh=[this]{updateInstrument(property("pendingMinute").toJsonObject());};}
 const QJsonObject input{{"id",s["id"]},{"quote",s["quote"]},{"minute",s["minute"]},{"minuteMeta",s["minuteMeta"]},{"name",r["name"]},{"dark",palette().color(QPalette::Window).lightness()<128}};
 if(!repaint->applying()){setProperty("pendingMinute",input);repaint->request();return;}
 if(!isVisible()||window()->isMinimized())return;const auto rows=s["minute"].toArray();
 if(property("appliedMinute").toJsonObject()==input&&chart->bars.size()==size_t(rows.size()))return;setProperty("appliedMinute",input);
auto q=s["quote"].toObject(),m=s["minuteMeta"].toObject();quoteState->setText(r["name"].toString()+" "+s["id"].toString()+"\n报价 "+fmt(q["price"])+" · "+q["source"].toString()+" · "+q["tradeDate"].toString()+" "+q["tradeTime"].toString()+(q["cached"].toBool()?" · 旧缓存":"")+"\n分时 "+m["source"].toString()+" · 检查 "+m["checkedAt"].toString()+(m["cached"].toBool()?" · 旧缓存":"")+" "+m["error"].toString());auto number=[](QJsonValue v){return v.isDouble()?v.toDouble():NAN;};chart->dark=palette().color(QPalette::Window).lightness()<128;chart->previousClose=number(m["previousClose"]);const QJsonObject series{{"id",s["id"]},{"rows",rows}};
 if(chart->property("liveSeriesInput").toJsonObject()==series&&chart->bars.size()==size_t(rows.size())){chart->update();return;}chart->setProperty("liveSeriesInput",series);
 std::vector<market::Bar> bars;QStringList labels;for(auto v:rows){auto x=v.toObject();bars.push_back({number(x["time"]),number(x["open"]),number(x["high"]),number(x["low"]),number(x["close"]),number(x["volume"]),x["valid"].toBool(),x["closed"].toBool()});labels<<x["label"].toString();}chart->setSeries(bars,labels,true,false);}
